document.getElementById("set-current-date").addEventListener("click",()=>{let t=Math.floor(Date.now()/1e3);document.getElementById("date").value=t});const updateCounter=(t,e,n)=>{let u=document.getElementById(t).value,r=u.length,o=document.getElementById(e);o.textContent=`${r}/${n}`,o.classList.toggle("text-red-500",r>n),o.classList.toggle("text-gray-400",r<=n)};updateCounter("summary","summary-counter",160),updateCounter("content","content-counter",1e5),document.getElementById("summary").addEventListener("input",()=>{updateCounter("summary","summary-counter",160)}),document.getElementById("content").addEventListener("input",()=>{updateCounter("content","content-counter",1e5)});